// ── Guided veto manager ─────────────────────────────────────────────────────
let _vetoGameInit = false;
el('btn-veto-start')?.addEventListener('click', () => {
  send('veto_start', {
    game: el('veto-game')?.value || '',
    bestOf: Number(el('veto-bestof')?.value || 3),
    teamStart: el('veto-start')?.value || 'a',
    visible: true
  });
});
